from solution import Entry, Report, solve

assert solve([], 0) == Report(0, 0, (-1)), 'fixture 0'
assert solve([], 5) == Report(0, 5, (-1)), 'fixture 1'
assert solve([], 1) == Report(0, 1, (-1)), 'fixture 2'
assert solve([Entry(3, 8)], 2) == Report(10, 10, (-1)), 'fixture 3'
assert solve([Entry(1, 6), Entry(3, 7)], 3) == Report(19, 9, (-1)), 'fixture 4'
assert solve([Entry(2, 11), Entry(0, 0), Entry(0, (-2))], 4) == Report(17, 2, (-1)), 'fixture 5'
assert solve([Entry(3, 10), Entry(2, 2), Entry(4, 0), Entry(0, 11)], 5) == Report(43, 5, (-1)), 'fixture 6'
assert solve([Entry(3, 10), Entry(0, 5), Entry(4, 2), Entry(1, 3), Entry(1, 1)], 6) == Report(45, 8, (-1)), 'fixture 7'
assert solve([Entry(3, 5), Entry(1, (-2)), Entry(3, 11), Entry(4, 2), Entry(0, 10), Entry(3, 6)], 7) == Report(60, 5, (-1)), 'fixture 8'
assert solve([Entry(1, 5), Entry(1, 1), Entry(3, (-1)), Entry(0, 8), Entry(3, 7), Entry(0, 5), Entry(1, 11)], 8) == Report(60, 7, (-1)), 'fixture 9'
assert solve([Entry(0, (-3)), Entry(1, 7), Entry(1, 7), Entry(3, (-2)), Entry(4, (-1)), Entry(0, 4), Entry(2, 8), Entry(1, (-2))], 1) == Report(23, (-2), 0), 'fixture 10'
assert solve([Entry(2, 10), Entry(2, 11), Entry(4, 2), Entry(3, 1), Entry(2, 1), Entry(2, 4), Entry(0, 2), Entry(3, (-3)), Entry(4, 2)], 2) == Report(38, 0, (-1)), 'fixture 11'
assert solve([Entry(0, 7), Entry(3, (-3)), Entry(1, 5), Entry(0, 10), Entry(1, 8), Entry(3, 6), Entry(0, 2), Entry(4, 5), Entry(2, (-1)), Entry(0, 1)], 3) == Report(55, 0, (-1)), 'fixture 12'
assert solve([Entry(2, 5), Entry(4, 3), Entry(3, 11), Entry(1, 8), Entry(3, 4), Entry(0, 1), Entry(4, 3), Entry(1, 5), Entry(4, 6), Entry(1, 9), Entry(4, 7)], 4) == Report(82, 5, (-1)), 'fixture 13'
assert solve([Entry(1, 3), Entry(1, 7), Entry(3, 4), Entry(2, 6), Entry(2, 11), Entry(1, 0), Entry(0, 2), Entry(1, 10), Entry(1, (-1)), Entry(0, (-1)), Entry(3, 11), Entry(3, (-3))], 5) == Report(69, 6, (-1)), 'fixture 14'
assert solve([], 6) == Report(0, 6, (-1)), 'fixture 15'
assert solve([Entry(3, (-1))], 7) == Report(6, 6, (-1)), 'fixture 16'
assert solve([Entry(0, 4), Entry(4, 8)], 8) == Report(28, 12, (-1)), 'fixture 17'
assert solve([Entry(3, 7), Entry(0, (-1)), Entry(0, 3)], 1) == Report(11, 0, (-1)), 'fixture 18'
assert solve([Entry(1, 11), Entry(0, 5), Entry(3, 4), Entry(0, 4)], 2) == Report(30, 6, (-1)), 'fixture 19'
assert solve([Entry(1, 1), Entry(2, 5), Entry(4, (-3)), Entry(2, 5), Entry(1, (-3))], 3) == Report(14, 0, (-1)), 'fixture 20'
assert solve([Entry(0, 4), Entry(2, 1), Entry(3, 10), Entry(4, (-3)), Entry(2, 4), Entry(1, 4)], 4) == Report(40, 1, (-1)), 'fixture 21'
assert solve([Entry(2, 1), Entry(0, 6), Entry(1, 6), Entry(0, 0), Entry(1, 0), Entry(2, 11), Entry(4, (-1))], 5) == Report(43, 4, (-1)), 'fixture 22'
assert solve([Entry(4, 6), Entry(4, (-1)), Entry(0, (-3)), Entry(2, 9), Entry(0, (-1)), Entry(0, 2), Entry(1, (-2)), Entry(1, (-1))], 6) == Report(33, 2, (-1)), 'fixture 23'
assert solve([Entry(0, 3), Entry(1, 6)], 5) == Report(19, 8, (-1)), 'fixture 24'
assert solve([Entry(0, (-5)), Entry(0, 1)], 5) == Report(1, 0, (-1)), 'fixture 25'
assert solve([Entry(0, (-6)), Entry(1, (-8))], 5) == Report((-4), (-3), 0), 'fixture 26'
assert solve([Entry(2, (-7)), Entry(2, 9), Entry(3, (-1))], 5) == Report(11, (-2), 0), 'fixture 27'
